	"github.com/gorilla/sessions"
	"github.com/labstack/echo-contrib/session"
	"github.com/labstack/echo/v4"
	"golang.org/x/crypto/bcrypt"
)

const (
	defaultSessionIDKey      = "SESSIONID"
	defaultSessionExpiresKey = "EXPIRES"
	defaultUserIDKey         = "USERID"
	defaultUsernameKey       = "USERNAME"
	bcryptDefaultCost        = bcrypt.MinCost
)

var fallbackImage = "../img/NoImage.jpg"

var errNotFound = sql.ErrNoRows

type UserModel struct {
	ID             int64  `db:"id"`
	Name           string `db:"name"`
	DisplayName    string `db:"display_name"`
	Description    string `db:"description"`
	HashedPassword string `db:"password"`
}

type User struct {
	ID          int64  `json:"id"`
	Name        string `json:"name"`
	DisplayName string `json:"display_name,omitempty"`
	Description string `json:"description,omitempty"`
	Theme       Theme  `json:"theme,omitempty"`
	IconHash    string `json:"icon_hash,omitempty"`
}

type Theme struct {
	ID       int64 `json:"id"`
	DarkMode bool  `json:"dark_mode"`
}

type ThemeModel struct {
	ID       int64 `db:"id"`
	UserID   int64 `db:"user_id"`
	DarkMode bool  `db:"dark_mode"`
}

type PostUserRequest struct {
	Name        string `json:"name"`
	DisplayName string `json:"display_name"`
	Description string `json:"description"`
	// Password is non-hashed password.
	Password string               `json:"password"`
	Theme    PostUserRequestTheme `json:"theme"`
}

type PostUserRequestTheme struct {
	DarkMode bool `json:"dark_mode"`
}

type LoginRequest struct {
	Username string `json:"username"`
	// Password is non-hashed password.
	Password string `json:"password"`
}

type PostIconRequest struct {
	Image []byte `json:"image"`
}

type PostIconResponse struct {
	ID int64 `json:"id"`
}

// content-addressed image cache (hash -> bytes); immutable entries
var (
	imageCacheMu sync.RWMutex
	imageCache   = map[string][]byte{}
)

func getIconHandler(c echo.Context) error {
	ctx := c.Request().Context()

	username := c.Param("username")

	user, err := getUserEntryByName(ctx, username)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return echo.NewHTTPError(http.StatusNotFound, "not found user that has the given username")
		}
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get user: "+err.Error())
	}

	var hash string
	if err := dbConn.GetContext(ctx, &hash, "SELECT hash FROM icons WHERE user_id = ?", user.ID); err != nil {
		if !errors.Is(err, sql.ErrNoRows) {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to get user icon: "+err.Error())
		}
		hash = ""
	}

	if inm := c.Request().Header.Get("If-None-Match"); inm != "" {
		h := hash
		if h == "" {
			h = fallbackImageHash
		}
		if strings.Trim(strings.TrimPrefix(inm, "W/"), "\"") == h {
			return c.NoContent(http.StatusNotModified)
		}
	}

	if hash == "" {
		return c.Blob(http.StatusOK, "image/jpeg", fallbackImageBytes)
	}

	imageCacheMu.RLock()
	img, ok := imageCache[hash]
	imageCacheMu.RUnlock()
	if !ok {
		if err := dbConn.GetContext(ctx, &img, "SELECT image FROM icons WHERE user_id = ?", user.ID); err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return c.Blob(http.StatusOK, "image/jpeg", fallbackImageBytes)
			}
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to get user icon: "+err.Error())
		}
		h := fmt.Sprintf("%x", sha256.Sum256(img))
		imageCacheMu.Lock()
		imageCache[h] = img
		imageCacheMu.Unlock()
	}

	return c.Blob(http.StatusOK, "image/jpeg", img)
}

func postIconHandler(c echo.Context) error {
	ctx := c.Request().Context()

	if err := verifyUserSession(c); err != nil {
		return err
	}

	sess, _ := session.Get(defaultSessionIDKey, c)
	userID := sess.Values[defaultUserIDKey].(int64)

	var req *PostIconRequest
	if err := json.NewDecoder(c.Request().Body).Decode(&req); err != nil {
		return echo.NewHTTPError(http.StatusBadRequest, "failed to decode the request body as json")
	}

	hash := fmt.Sprintf("%x", sha256.Sum256(req.Image))
	imageCacheMu.Lock()
	imageCache[hash] = bytes.Clone(req.Image)
	imageCacheMu.Unlock()

	tx, err := dbConn.BeginTxx(ctx, nil)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to begin transaction: "+err.Error())
	}
	defer tx.Rollback()

	if _, err := tx.ExecContext(ctx, "DELETE FROM icons WHERE user_id = ?", userID); err != nil {
