		args := make([]interface{}, 0, len(req.Tags)*2)
		for i, tagID := range req.Tags {
			if i > 0 {
				q += ","
			}
			q += "(?, ?)"
			args = append(args, livestreamID, tagID)
		}
		if _, err := tx.ExecContext(ctx, q, args...); err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to insert livestream tag: "+err.Error())
		}
	}

	if err := tx.Commit(); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to commit: "+err.Error())
	}

	e := &lsEntry{Model: livestreamModel, Tags: tags}
	putLivestreamCache(e)

	return c.JSON(http.StatusCreated, toLivestream(e, owner))
}

