package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/jmoiron/sqlx"
	"github.com/labstack/echo-contrib/session"
	"github.com/labstack/echo/v4"
)

type PostLivecommentRequest struct {
	Comment string `json:"comment"`
	Tip     int64  `json:"tip"`
}

type LivecommentModel struct {
	ID           int64  `db:"id"`
	UserID       int64  `db:"user_id"`
	LivestreamID int64  `db:"livestream_id"`
	Comment      string `db:"comment"`
	Tip          int64  `db:"tip"`
	CreatedAt    int64  `db:"created_at"`
}

type Livecomment struct {
	ID         int64      `json:"id"`
	User       User       `json:"user"`
	Livestream Livestream `json:"livestream"`
	Comment    string     `json:"comment"`
	Tip        int64      `json:"tip"`
	CreatedAt  int64      `json:"created_at"`
}

type LivecommentReport struct {
	ID          int64       `json:"id"`
	Reporter    User        `json:"reporter"`
	Livecomment Livecomment `json:"livecomment"`
	CreatedAt   int64       `json:"created_at"`
}

type LivecommentReportModel struct {
	ID            int64 `db:"id"`
	UserID        int64 `db:"user_id"`
	LivestreamID  int64 `db:"livestream_id"`
	LivecommentID int64 `db:"livecomment_id"`
	CreatedAt     int64 `db:"created_at"`
}

type ModerateRequest struct {
	NGWord string `json:"ng_word"`
}

type NGWord struct {
	ID           int64  `json:"id" db:"id"`
	UserID       int64  `json:"user_id" db:"user_id"`
	LivestreamID int64  `json:"livestream_id" db:"livestream_id"`
	Word         string `json:"word" db:"word"`
	CreatedAt    int64  `json:"created_at" db:"created_at"`
}

// ---- LIKE '%word%' emulation ----

var (
	likeMu    sync.RWMutex
	likeCache = map[string]*regexp.Regexp{}
)

func likeContains(text, word string) bool {
	if !strings.ContainsAny(word, "%_\\") {
		return strings.Contains(text, word)
	}
	likeMu.RLock()
	re, ok := likeCache[word]
	likeMu.RUnlock()
	if !ok {
		var b strings.Builder
		b.WriteString("(?s)")
		rs := []rune(word)
		for i := 0; i < len(rs); i++ {
			r := rs[i]
			switch r {
			case '%':
				b.WriteString(".*")
			case '_':
				b.WriteString(".")
			case '\\':
				if i+1 < len(rs) {
					i++
					b.WriteString(regexp.QuoteMeta(string(rs[i])))
				} else {
					b.WriteString(regexp.QuoteMeta("\\"))
				}
			default:
				b.WriteString(regexp.QuoteMeta(string(r)))
			}
		}
		var err error
		re, err = regexp.Compile(b.String())
		if err != nil {
			return strings.Contains(text, word)
		}
		likeMu.Lock()
		likeCache[word] = re
		likeMu.Unlock()
	}
	return re.MatchString(text)
}

// ---- builders ----

func buildLivecomments(ctx context.Context, models []LivecommentModel) ([]Livecomment, error) {
	lsIDs := make([]int64, 0, 4)
	userIDs := make([]int64, 0, len(models))
	seenLs := map[int64]struct{}{}
	for _, m := range models {
		if _, ok := seenLs[m.LivestreamID]; !ok {
			seenLs[m.LivestreamID] = struct{}{}
			lsIDs = append(lsIDs, m.LivestreamID)
		}
		userIDs = append(userIDs, m.UserID)
	}
	lss, users, err := buildLivestreams(ctx, lsIDs, userIDs)
	if err != nil {
		return nil, err
	}
	lsMap := make(map[int64]Livestream, len(lss))
	for _, l := range lss {
		lsMap[l.ID] = l
	}
	out := make([]Livecomment, len(models))
	for i, m := range models {
		u, ok := users[m.UserID]
		if !ok {
			return nil, errNotFound
		}
		out[i] = Livecomment{
			ID:         m.ID,
			User:       u,
			Livestream: lsMap[m.LivestreamID],
			Comment:    m.Comment,
			Tip:        m.Tip,
			CreatedAt:  m.CreatedAt,
		}
	}
	return out, nil
}

func buildReports(ctx context.Context, q sqlx.QueryerContext, reportModels []*LivecommentReportModel) ([]LivecommentReport, error) {
	reports := make([]LivecommentReport, len(reportModels))
	if len(reportModels) == 0 {
		return reports, nil
	}
	lcIDs := make([]int64, 0, len(reportModels))
	for _, r := range reportModels {
		lcIDs = append(lcIDs, r.LivecommentID)
	}
	lcIDs = uniqIDs(lcIDs)
	query, args, err := sqlx.In("SELECT * FROM livecomments WHERE id IN (?)", lcIDs)
	if err != nil {
		return nil, err
	}
	var lcModels []LivecommentModel
	if err := sqlx.SelectContext(ctx, q, &lcModels, query, args...); err != nil {
		return nil, err
	}
	extraUsers := make([]int64, 0, len(reportModels))
	for _, r := range reportModels {
		extraUsers = append(extraUsers, r.UserID)
	}
	lcs, err := buildLivecomments(ctx, lcModels)
	if err != nil {
		return nil, err
	}
	lcMap := make(map[int64]Livecomment, len(lcs))
	for _, lc := range lcs {
		lcMap[lc.ID] = lc
	}
	reporters, err := buildUsers(ctx, extraUsers)
	if err != nil {
		return nil, err
	}
	for i, r := range reportModels {
		lc, ok := lcMap[r.LivecommentID]
		if !ok {
			return nil, errNotFound
		}
		rep, ok := reporters[r.UserID]
		if !ok {
			return nil, errNotFound
		}
		reports[i] = LivecommentReport{
			ID:          r.ID,
			Reporter:    rep,
			Livecomment: lc,
			CreatedAt:   r.CreatedAt,
		}
	}
	return reports, nil
}

func getLivecommentsHandler(c echo.Context) error {
