		K int64 `db:"k"`
		V int64 `db:"v"`
	}
	var reactionRows []kv
	if err := dbConn.SelectContext(ctx, &reactionRows, "SELECT l.user_id AS k, COUNT(*) AS v FROM reactions r INNER JOIN livestreams l ON l.id = r.livestream_id GROUP BY l.user_id"); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to count reactions: "+err.Error())
	}
	var tipRows []kv
	if err := dbConn.SelectContext(ctx, &tipRows, "SELECT l.user_id AS k, IFNULL(SUM(lc.tip), 0) AS v FROM livecomments lc INNER JOIN livestreams l ON l.id = lc.livestream_id GROUP BY l.user_id"); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to count tips: "+err.Error())
	}
