	for _, r := range reactionRows {
		scores[r.K] += r.V
	}
	for _, r := range tipRows {
		scores[r.K] += r.V
	}
	myScore := scores[user.ID]
	var rank int64 = 1
	for _, u := range users {
		s := scores[u.ID]
		if s > myScore || (s == myScore && u.Name > username) {
			rank++
		}
	}

