		FavoriteEmoji:     favoriteEmoji,
	}
	return c.JSON(http.StatusOK, stats)
}

func getLivestreamStatisticsHandler(c echo.Context) error {
	ctx := c.Request().Context()

	if err := verifyUserSession(c); err != nil {
		return err
	}

	id, err := strconv.Atoi(c.Param("livestream_id"))
	if err != nil {
		return echo.NewHTTPError(http.StatusBadRequest, "livestream_id in path must be integer")
	}
	livestreamID := int64(id)

	if _, err := getLivestreamEntry(ctx, livestreamID); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return echo.NewHTTPError(http.StatusBadRequest, "cannot get stats of not found livestream")
		}
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livestream: "+err.Error())
	}

	type kv struct {
		K int64 `db:"k"`
		V int64 `db:"v"`
	}
	var reactionRows []kv
	if err := dbConn.SelectContext(ctx, &reactionRows, "SELECT livestream_id AS k, COUNT(*) AS v FROM reactions GROUP BY livestream_id"); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to count reactions: "+err.Error())
	}
	var tipRows []kv
	if err := dbConn.SelectContext(ctx, &tipRows, "SELECT livestream_id AS k, IFNULL(SUM(tip), 0) AS v FROM livecomments GROUP BY livestream_id"); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to count tips: "+err.Error())
	}
	scores := make(map[int64]int64, len(reactionRows)+len(tipRows))
	var totalReactions int64
	for _, r := range reactionRows {
		scores[r.K] += r.V
		if r.K == livestreamID {
			totalReactions = r.V
		}
	}
	for _, r := range tipRows {
		scores[r.K] += r.V
	}
	myScore := scores[livestreamID]
	var rank int64 = 1
	// livestreams with nonzero score ranked above
	var nonzeroAboveByID int64 // nonzero-score entries with id > mine and score == 0 case handled below
	for k, s := range scores {
		if s == 0 {
			continue
		}
		if s > myScore || (s == myScore && k > livestreamID) {
			rank++
		}
		if k > livestreamID {
			nonzeroAboveByID++
		}
	}
	if myScore == 0 {
		// zero-score livestreams with id > mine are also ranked above
		var cntAbove int64
		if err := dbConn.GetContext(ctx, &cntAbove, "SELECT COUNT(*) FROM livestreams WHERE id > ?", livestreamID); err != nil {
			return echo.NewHTTPError(http.StatusInternalServerError, "failed to count livestreams: "+err.Error())
		}
		rank += cntAbove - nonzeroAboveByID
	}

	var viewersCount int64
	if err := dbConn.GetContext(ctx, &viewersCount, `SELECT COUNT(*) FROM livestream_viewers_history WHERE livestream_id = ?`, livestreamID); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to count livestream viewers: "+err.Error())
	}

	var maxTip int64
	if err := dbConn.GetContext(ctx, &maxTip, `SELECT IFNULL(MAX(tip), 0) FROM livecomments WHERE livestream_id = ?`, livestreamID); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to find maximum tip livecomment: "+err.Error())
	}

	var totalReports int64
	if err := dbConn.GetContext(ctx, &totalReports, `SELECT COUNT(*) FROM livecomment_reports WHERE livestream_id = ?`, livestreamID); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to count total spam reports: "+err.Error())
	}

	return c.JSON(http.StatusOK, LivestreamStatistics{
		Rank:           rank,
		ViewersCount:   viewersCount,
		MaxTip:         maxTip,
		TotalReactions: totalReactions,
		TotalReports:   totalReports,
	})
}
