// internal: serve raw icon file for peers
func internalIconFileHandler(c echo.Context) error {
	uid, err := strconv.ParseInt(c.QueryParam("user_id"), 10, 64)
	if err != nil {
		return c.NoContent(http.StatusBadRequest)
	}
	b, err := os.ReadFile(iconPath(uid))
	if err != nil {
		return c.NoContent(http.StatusNotFound)
	}
	return c.Blob(http.StatusOK, "application/octet-stream", b)
}

var iconDir = "/home/isucon/icons"

func iconPath(uid int64) string {
	return filepath.Join(iconDir, strconv.FormatInt(uid, 10)+".jpg")
}

func storeIconImage(uid int64, hash string, img []byte) {
	cp := bytes.Clone(img)
	imageCacheMu.Lock()
	imageCache[hash] = cp
	imageCacheMu.Unlock()
	tmp := iconPath(uid) + fmt.Sprintf(".tmp%d", time.Now().UnixNano())
	if err := os.WriteFile(tmp, cp, 0644); err != nil {
		log.Printf("write icon: %v", err)
		return
	}
	if err := os.Rename(tmp, iconPath(uid)); err != nil {
		log.Printf("rename icon: %v", err)
	}
}

func loadIconImage(ctx context.Context, uid int64, hash string) ([]byte, bool) {
	imageCacheMu.RLock()
	img, ok := imageCache[hash]
	imageCacheMu.RUnlock()
	if ok {
		return img, true
	}
	if b, err := os.ReadFile(iconPath(uid)); err == nil {
		h := fmt.Sprintf("%x", sha256.Sum256(b))
		if h == hash {
			imageCacheMu.Lock()
			imageCache[h] = b
			imageCacheMu.Unlock()
			return b, true
		}
	}
	// legacy: image stored in DB
	var dbImg []byte
	if err := dbConn.GetContext(ctx, &dbImg, "SELECT image FROM icons WHERE user_id = ?", uid); err == nil && len(dbImg) > 0 {
		return dbImg, true
	}
	// ask peers
	for _, p := range peerURLs {
		resp, err := dnsHTTPClnt.Get(p + "/api/internal/iconfile?user_id=" + strconv.FormatInt(uid, 10))
		if err != nil {
			continue
		}
		b, err := io.ReadAll(resp.Body)
		resp.Body.Close()
		if err == nil && resp.StatusCode == http.StatusOK && len(b) > 0 {
			h := fmt.Sprintf("%x", sha256.Sum256(b))
			storeIconImage(uid, h, b)
			return b, true
		}
	}
	return nil, false
}

func resetIconFiles() {
	imageCacheMu.Lock()
	imageCache = map[string][]byte{}
	imageCacheMu.Unlock()
	entries, err := os.ReadDir(iconDir)
	if err != nil {
		return
	}
	for _, e := range entries {
		os.Remove(filepath.Join(iconDir, e.Name()))
	}
}
